#include <iostream>
#include <vector>
class Query { // Abstract Base Class
public:
  virtual ~Query() = default;
  virtual bool eval() const = 0;
};
class AndQuery : public Query {
public:
  AndQuery(const Query& left, const Query& right) : left_(left), right_(right) {}
  bool eval() const override { return left_.eval() && right_.eval(); }
private:
  const Query& left_;
  const Query& right_;
};
class OrQuery : public Query {
public:
  OrQuery(const Query& left, const Query& right) : left_(left), right_(right) {}
  bool eval() const override { return left_.eval() || right_.eval(); }
private:
  const Query& left_;
  const Query& right_;
};
class SimpleQuery : public Query { // Example of a simple query
public:
  SimpleQuery(bool result) : result_(result) {}
  bool eval() const override { return result_; }
private:
  bool result_;
};
int main() {
  SimpleQuery q1(true);
  SimpleQuery q2(false);
  AndQuery andQuery(q1, q2);
  OrQuery orQuery(q1, q2);
  std::cout << "AndQuery result: " << andQuery.eval() << std::endl; //false
  std::cout << "OrQuery result: " << orQuery.eval() << std::endl;   //true
  return 0;
}
